+  if (!hdrRow) {
+    // We failed to create a new row. That can happen if we run out of keys,
+    // which will force a reparse.
+    nsTArray<nsMsgKey> keys;
+    if (NS_SUCCEEDED(ListAllKeys(keys))) {
